export function mergeFeedbackById(...lists: Array<FeedbackEntry[] | undefined>): FeedbackEntry[] {
	const byFeedbackId = new Map<string, FeedbackEntry>();
	for (const list of lists) {
		for (const entry of list ?? []) {
