function hasOrderedTimestamps(createdAt: unknown, updatedAt: unknown): boolean {
  return isContractTimestamp(createdAt) && isContractTimestamp(updatedAt)
    && compareContractTimestamps(updatedAt, createdAt) >= 0;
}

