import {
  BoxRenderable,
  CliRenderEvents,
  InputRenderable,
  SelectRenderable,
  SelectRenderableEvents,
  ScrollBoxRenderable,
  TextRenderable,
  createCliRenderer,
} from "@opentui/core";

import { launchRpcClient } from "../runtime/pi.js";
import { HostController, type HostSurface } from "./host-controller.js";
import {
  EMPTY_HEADER_STATE,
  TUI_COMMANDS,
  activityText,
  commandOption,
  headerText,
  sanitizeDiagnostic,
  showActivityRail,
  transcriptText,
  type TranscriptEntry,
  type TuiCommand,
  type TuiHeaderState,
} from "./view-model.js";

export type OpenTuiExitAction = "exit" | "shell";

/** Run the alternate OpenTUI host over Pi RPC. `keating shell` remains intact. */
export async function launchOpenTui(cwd: string, initialPrompt?: string): Promise<OpenTuiExitAction> {
  const client = await launchRpcClient(cwd);
  let settle: ((action: OpenTuiExitAction) => void) | null = null;
  let settled = false;
  const result = new Promise<OpenTuiExitAction>((resolve) => { settle = resolve; });
  const renderer = await createCliRenderer({
    exitOnCtrlC: true,
    clearOnShutdown: true,
    backgroundColor: "#11100e",
    onDestroy: () => {
      if (!settled) {
        settled = true;
        settle?.("exit");
      }
      void client.stop();
    },
  });

  const shell = new BoxRenderable(renderer, {
    id: "keating-open-tui",
    width: "100%",
    height: "100%",
    flexDirection: "column",
    padding: 1,
    gap: 0,
    backgroundColor: "#11100e",
  });
  const header = new TextRenderable(renderer, {
    id: "keating-open-tui-header",
    content: headerText(EMPTY_HEADER_STATE),
    fg: "#d6a84d",
    height: 1,
  });
  const status = new TextRenderable(renderer, {
    id: "keating-open-tui-status",
    content: "Ctrl+P commands  ·  Ctrl+M model  ·  Ctrl+T thinking  ·  Ctrl+N new  ·  Ctrl+X stop",
    fg: "#9d9485",
    height: 1,
  });
  const workspace = new BoxRenderable(renderer, {
    id: "keating-open-tui-workspace",
    flexGrow: 1,
    width: "100%",
    flexDirection: "row",
    gap: 1,
  });
  const scroll = new ScrollBoxRenderable(renderer, {
    id: "keating-open-tui-transcript-scroll",
    flexGrow: 1,
    border: true,
    borderStyle: "single",
    borderColor: "#4c463d",
    padding: 1,
    scrollY: true,
    stickyScroll: true,
    stickyStart: "bottom",
  });
  const transcript = new TextRenderable(renderer, {
    id: "keating-open-tui-transcript",
    content: "Ask a question, continue a learning goal, or type /shell for the classic Pi interface.",
    fg: "#eee8dc",
    width: "100%",
  });
  const activityRail = new BoxRenderable(renderer, {
    id: "keating-open-tui-activity-rail",
    width: 30,
    height: "100%",
    border: true,
    borderStyle: "single",
    borderColor: "#4c463d",
    padding: 1,
  });
  const activity = new TextRenderable(renderer, {
    id: "keating-open-tui-activity",
    content: "SESSION\nnew session\n\nACTIVITY\n· No tool activity yet",
    fg: "#9d9485",
    width: "100%",
  });
  const inputFrame = new BoxRenderable(renderer, {
    id: "keating-open-tui-input-frame",
    width: "100%",
    height: 3,
    border: true,
    borderStyle: "single",
    borderColor: "#d6a84d",
    paddingLeft: 1,
    paddingRight: 1,
  });
  const input = new InputRenderable(renderer, {
    id: "keating-open-tui-input",
    width: "100%",
    placeholder: "Message Keating…",
    textColor: "#eee8dc",
    placeholderColor: "#81786b",
    backgroundColor: "#11100e",
    focusedBackgroundColor: "#11100e",
    focusedTextColor: "#ffffff",
  });

  scroll.add(transcript);
  activityRail.add(activity);
  workspace.add(scroll);
  workspace.add(activityRail);
  inputFrame.add(input);
  shell.add(header);
  shell.add(status);
  shell.add(workspace);
  shell.add(inputFrame);
  renderer.root.add(shell);

  const entries: TranscriptEntry[] = [];
  let streaming: TranscriptEntry | null = null;
  let headerState: TuiHeaderState = { ...EMPTY_HEADER_STATE };
  let headerLabel = "KEATING";
  let busy = false;
  let dialogCancel: (() => void) | null = null;
  const renderTranscript = () => {
    transcript.content = transcriptText(entries, streaming);
    activity.content = activityText(entries, headerState);
    scroll.scrollTo({ y: scroll.scrollHeight, x: 0 });
  };
  const renderHeader = () => {
    header.content = headerText(headerState).replace(/^KEATING/, headerLabel.toUpperCase());
  };
  const appendEntry = (entry: TranscriptEntry) => {
    entries.push(entry);
    renderTranscript();
  };
  const updateResponsiveLayout = (width: number) => {
    activityRail.visible = showActivityRail(width);
  };
  updateResponsiveLayout(renderer.terminalWidth);
  renderer.on(CliRenderEvents.RESIZE, updateResponsiveLayout);

  const presentSelect = (title: string, options: string[]): Promise<string | undefined> =>
    new Promise((resolve) => {
      const modal = new BoxRenderable(renderer, {
        id: `keating-dialog-${Date.now()}`,
        width: "100%",
        height: Math.min(Math.max(options.length + 4, 6), 16),
        flexDirection: "column",
        border: true,
        borderStyle: "single",
        borderColor: "#d6a84d",
        padding: 1,
      });
      const titleView = new TextRenderable(renderer, { content: `${title}  ·  Esc cancels`, fg: "#d6a84d", height: 1 });
      const select = new SelectRenderable(renderer, {
        id: `keating-select-${Date.now()}`,
        flexGrow: 1,
        options: options.map((option) => ({ name: option, description: "", value: option })),
        showDescription: false,
        wrapSelection: true,
        selectedBackgroundColor: "#d6a84d",
        selectedTextColor: "#11100e",
      });
      modal.add(titleView);
      modal.add(select);
      shell.add(modal, 3);
      let done = false;
      const finish = (value?: string) => {
        if (done) return;
        done = true;
        dialogCancel = null;
        shell.remove(modal);
        renderer.focusRenderable(input);
        resolve(value);
      };
      dialogCancel = () => finish(undefined);
      select.on(SelectRenderableEvents.ITEM_SELECTED, () => finish(select.getSelectedOption()?.value as string | undefined));
      renderer.focusRenderable(select);
    });

  const presentTextInput = (title: string, prefill?: string, placeholder?: string): Promise<string | undefined> =>
    new Promise((resolve) => {
      const modal = new BoxRenderable(renderer, {
        id: `keating-input-dialog-${Date.now()}`,
        width: "100%",
        height: 5,
        flexDirection: "column",
        border: true,
        borderStyle: "single",
        borderColor: "#d6a84d",
        padding: 1,
      });
      const titleView = new TextRenderable(renderer, {
        content: `${title}  ·  Enter submits  ·  Esc cancels`,
        fg: "#d6a84d",
        height: 1,
      });
      const dialogInput = new InputRenderable(renderer, {
        id: `keating-dialog-input-${Date.now()}`,
        width: "100%",
        value: prefill ?? "",
        placeholder: placeholder ?? "Type a response…",
        textColor: "#eee8dc",
        placeholderColor: "#81786b",
        backgroundColor: "#11100e",
        focusedBackgroundColor: "#11100e",
        focusedTextColor: "#ffffff",
      });
      modal.add(titleView);
      modal.add(dialogInput);
      shell.add(modal, 3);
      let done = false;
      const finish = (value?: string) => {
        if (done) return;
        done = true;
        dialogCancel = null;
        shell.remove(modal);
        renderer.focusRenderable(input);
        resolve(value);
      };
      dialogCancel = () => finish(undefined);
      dialogInput.onSubmit = () => finish(dialogInput.value);
      renderer.focusRenderable(dialogInput);
    });

  const surface: HostSurface = {
    hydrateEntries(next) { entries.splice(0, entries.length, ...next); renderTranscript(); },
    appendEntry,
    setStreaming(entry) { streaming = entry; renderTranscript(); },
    setStatus(text) { status.content = text; },
    setHeaderState(next) {
      headerState = { ...headerState, ...next };
      busy = headerState.busy;
      renderHeader();
      renderTranscript();
      status.content = busy
        ? "Keating is thinking…  ·  Enter queues a follow-up  ·  Ctrl+X stops"
        : "Ctrl+P commands  ·  Ctrl+M model  ·  Ctrl+T thinking  ·  Ctrl+N new  ·  Ctrl+X stop";
    },
    setEditorText(text) { input.value = text; },
    setWidget(key, lines, placement) {
      if (lines?.length) appendEntry({
        id: `widget-${key}-${Date.now()}`,
        kind: "artifact",
        title: key,
        body: lines.join("\n"),
        detail: placement,
      });
    },
    setTitle(title) { headerLabel = title || "KEATING"; renderHeader(); },
    presentSelect,
    presentConfirm(title, message) { return presentSelect(`${title}\n${message}`, ["Yes", "No"]).then((value) => value === undefined ? undefined : value === "Yes"); },
    presentInput(title, placeholder) { return presentTextInput(title, undefined, placeholder); },
    presentEditor(title, prefill) { return presentTextInput(title, prefill, "Edit response…"); },
  };
  const controller = new HostController(client, surface);
  controller.attach();
  await controller.initialize();

  const exitToShell = async () => {
    settled = true;
    settle?.("shell");
    renderer.destroy();
    await client.stop();
  };

  const runCommand = async (command: TuiCommand): Promise<void> => {
    switch (command.id) {
      case "model":
        await controller.cycleModel();
        return;
      case "thinking":
        await controller.cycleThinking();
        return;
      case "new-session": {
        const confirmed = entries.length === 0
          ? true
          : await surface.presentConfirm("Start a new session?", "Your current session remains saved and can be reopened in Pi.");
        if (confirmed) await controller.newSession();
        return;
      }
      case "abort":
        await controller.abort();
        return;
      case "shell":
        await exitToShell();
    }
  };

  const showCommandPalette = async () => {
    const options = TUI_COMMANDS.map(commandOption);
    const selected = await presentSelect("Keating commands", options);
    const index = selected === undefined ? -1 : options.indexOf(selected);
    if (index >= 0) await runCommand(TUI_COMMANDS[index]!);
  };

  const submit = async (raw: string) => {
    const message = raw.trim();
    if (!message) return;
    input.value = "";
    if (message === "/shell") {
      await exitToShell();
      return;
    }
    const slashCommands: Record<string, TuiCommand["id"] | "palette"> = {
      "/commands": "palette",
      "/model": "model",
      "/thinking": "thinking",
      "/new": "new-session",
      "/abort": "abort",
    };
    const commandId = slashCommands[message];
    if (commandId) {
      if (commandId === "palette") await showCommandPalette();
      else {
        const command = TUI_COMMANDS.find((candidate) => candidate.id === commandId);
        if (command) await runCommand(command);
      }
      return;
    }
    appendEntry({ id: `user-${Date.now()}`, kind: "user", title: "You", body: message });
    try {
      if (busy) await client.followUp(message);
      else await client.prompt(message);
    } catch (error) {
      appendEntry({
        id: `submit-error-${Date.now()}`,
        kind: "error",
        title: "Message not sent",
        body: sanitizeDiagnostic(error),
      });
    }
  };

  input.onSubmit = () => { void submit(input.value); };
  renderer.keyInput.on("keypress", (key) => {
    if (key.name === "escape" && dialogCancel) {
      key.preventDefault();
      dialogCancel();
      return;
    }
    if (dialogCancel || !key.ctrl) return;
    const commandByKey: Partial<Record<string, TuiCommand["id"] | "palette">> = {
      p: "palette",
      m: "model",
      t: "thinking",
      n: "new-session",
      x: "abort",
    };
    const commandId = commandByKey[key.name];
    if (!commandId) return;
    key.preventDefault();
    key.stopPropagation();
    if (commandId === "palette") void showCommandPalette();
    else {
      const command = TUI_COMMANDS.find((candidate) => candidate.id === commandId);
      if (command) void runCommand(command);
    }
  });
  renderer.focusRenderable(input);
  renderer.start();
  if (initialPrompt?.trim()) void submit(initialPrompt);

  return result;
}
import { toolResultCardLines } from "../core/cards.js";
import {
  messageText,
  sanitizeDiagnostic,
  transcriptEntriesFromMessages,
  type TranscriptEntry,
  type TuiHeaderState,
} from "./view-model.js";

/**
 * Renderer-free controller for RPC hosts. Translates pi RPC events into
 * calls on a HostSurface, and services extension UI requests (select,
 * confirm, input, editor) by presenting them through the surface and
 * sending extension_ui_response commands back. The OpenTUI host implements
 * HostSurface with real widgets; tests implement it with scripted answers.
 */

export interface HostSurface {
  /** Replace the transcript with hydrated session history. */
  hydrateEntries(entries: TranscriptEntry[]): void;
  /** Append a completed, semantically typed transcript entry. */
  appendEntry(entry: TranscriptEntry): void;
  /** Replace the in-progress streaming assistant entry (null clears it). */
  setStreaming(entry: TranscriptEntry | null): void;
  setStatus(text: string): void;
  setHeaderState(state: Partial<TuiHeaderState>): void;
  setEditorText(text: string): void;
  setWidget(key: string, lines: string[] | undefined, placement?: string): void;
  setTitle(title: string): void;
  /** Resolve with the chosen option string, or undefined when cancelled. */
  presentSelect(title: string, options: string[]): Promise<string | undefined>;
  /** Resolve with the decision, or undefined when cancelled. */
  presentConfirm(title: string, message: string): Promise<boolean | undefined>;
  presentInput(title: string, placeholder?: string): Promise<string | undefined>;
  presentEditor(title: string, prefill?: string): Promise<string | undefined>;
}

export interface HostClientLike {
  onEvent(listener: (event: unknown) => void): unknown;
  getMessages?(): Promise<unknown[]>;
  getState?(): Promise<unknown>;
  cycleModel?(): Promise<{ model: { provider?: string; id?: string }; thinkingLevel?: string } | null>;
  cycleThinkingLevel?(): Promise<{ level: string } | null>;
  newSession?(): Promise<{ cancelled: boolean }>;
  abort?(): Promise<void>;
}

interface UiRequestEvent {
  type: "extension_ui_request";
  id?: string;
  method?: string;
  title?: string;
  options?: string[];
  message?: string;
  placeholder?: string;
  prefill?: string;
  statusText?: string;
  text?: string;
  widgetKey?: string;
  widgetLines?: string[];
  widgetPlacement?: string;
  document?: unknown;
  notifyType?: "info" | "warning" | "error";
}

function briefArgs(args: unknown): string {
  if (!args || typeof args !== "object") return "";
  const entries = Object.entries(args as Record<string, unknown>)
    .filter(([, value]) => typeof value === "string" || typeof value === "number" || typeof value === "boolean")
    .slice(0, 3)
    .map(([key, value]) => {
      const text = /(?:key|token|secret|password)/i.test(key) ? "[redacted]" : sanitizeDiagnostic(String(value), 80);
      return `${key}=${text.length > 40 ? `${text.slice(0, 40)}…` : text}`;
    });
  return entries.join(", ");
}

export class HostController {
  private client: HostClientLike;
  private surface: HostSurface;
  /** Serializes UI requests: pi awaits each dialog, but never assume only one is outstanding. */
  private uiQueue: Promise<void> = Promise.resolve();
  private entrySequence = 0;

  constructor(client: HostClientLike, surface: HostSurface) {
    this.client = client;
    this.surface = surface;
  }

  attach(): void {
    this.client.onEvent((event) => this.handleEvent(event));
  }

  async initialize(): Promise<void> {
    const [messages, state] = await Promise.allSettled([
      this.client.getMessages?.() ?? Promise.resolve([]),
      this.client.getState?.() ?? Promise.resolve(undefined),
    ]);
    if (messages.status === "fulfilled") {
      this.surface.hydrateEntries(transcriptEntriesFromMessages(messages.value));
    } else {
      this.appendError("Session history unavailable", messages.reason);
    }
    if (state.status === "fulfilled" && state.value) this.applySessionState(state.value);
    else if (state.status === "rejected") this.appendError("Session state unavailable", state.reason);
  }

  private nextId(prefix: string): string {
    this.entrySequence += 1;
    return `${prefix}-${Date.now()}-${this.entrySequence}`;
  }

  private append(kind: TranscriptEntry["kind"], title: string, body: string, detail?: string): void {
    this.surface.appendEntry({ id: this.nextId(kind), kind, title, body, detail });
  }

  private appendError(title: string, error: unknown): void {
    this.append("error", title, sanitizeDiagnostic(error) || "No diagnostic was provided.");
  }

  private applySessionState(raw: unknown): void {
    const state = raw as {
      model?: { provider?: string; id?: string };
      thinkingLevel?: string;
      sessionName?: string;
      sessionId?: string;
      sessionFile?: string;
      isStreaming?: boolean;
    };
    const provider = state.model?.provider;
    const modelId = state.model?.id;
    const model = [provider, modelId].filter(Boolean).join("/") || "model unavailable";
    const sessionFileName = state.sessionFile?.split(/[\\/]/).at(-1)?.replace(/\.jsonl$/, "");
    this.surface.setHeaderState({
      model,
      thinking: state.thinkingLevel || "off",
      session: state.sessionName || sessionFileName || state.sessionId || "new session",
      busy: Boolean(state.isStreaming),
    });
  }

  async cycleModel(): Promise<void> {
    if (!this.client.cycleModel) return this.appendError("Model change unavailable", "This Pi runtime does not support model cycling.");
    try {
      const result = await this.client.cycleModel();
      if (!result) {
        this.append("notice", "Model unchanged", "No other configured model is available.");
        return;
      }
      const model = [result.model.provider, result.model.id].filter(Boolean).join("/");
      this.surface.setHeaderState({ model, ...(result.thinkingLevel ? { thinking: result.thinkingLevel } : {}) });
      this.append("notice", "Model changed", model);
    } catch (error) {
      this.appendError("Could not change model", error);
    }
  }

  async cycleThinking(): Promise<void> {
    if (!this.client.cycleThinkingLevel) return this.appendError("Thinking change unavailable", "This Pi runtime does not support thinking controls.");
    try {
      const result = await this.client.cycleThinkingLevel();
      if (!result) {
        this.append("notice", "Thinking unchanged", "The current model does not expose another thinking level.");
        return;
      }
      this.surface.setHeaderState({ thinking: result.level });
      this.append("notice", "Thinking changed", result.level);
    } catch (error) {
      this.appendError("Could not change thinking", error);
    }
  }

  async newSession(): Promise<void> {
    if (!this.client.newSession) return this.appendError("New session unavailable", "This Pi runtime does not support session reset.");
    try {
      const result = await this.client.newSession();
      if (result.cancelled) {
        this.append("notice", "New session cancelled", "The current session is still active.");
        return;
      }
      this.surface.setStreaming(null);
      this.surface.hydrateEntries([]);
      this.surface.setHeaderState({ session: "new session", busy: false });
      this.append("notice", "Fresh session", "Ready for a new learning goal.");
      if (this.client.getState) this.applySessionState(await this.client.getState());
    } catch (error) {
      this.appendError("Could not start a new session", error);
    }
  }

  async abort(): Promise<void> {
    if (!this.client.abort) return this.appendError("Stop unavailable", "This Pi runtime does not support aborting a response.");
    try {
      await this.client.abort();
      this.surface.setStreaming(null);
      this.surface.setHeaderState({ busy: false });
      this.append("notice", "Response stopped", "Your draft and conversation are preserved.");
    } catch (error) {
      this.appendError("Could not stop the response", error);
    }
  }

  private async sendUiResponse(requestId: string, response: Record<string, unknown>): Promise<void> {
    const internal = this.client as unknown as { send?: (command: Record<string, unknown>) => Promise<unknown> };
    if (!internal.send) throw new Error("The Pi runtime cannot answer extension UI requests.");
    await internal.send({ type: "extension_ui_response", id: requestId, ...response });
  }

  handleEvent(event: unknown): void {
    const candidate = event as { type?: string } | null;
    if (!candidate || typeof candidate !== "object") return;

    switch (candidate.type) {
      case "message_update": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          const hydrated = transcriptEntriesFromMessages([message]);
          const entry = hydrated.find((item) => item.kind === "assistant");
          if (entry) this.surface.setStreaming({ ...entry, id: "assistant-streaming" });
        }
        return;
      }
      case "message_end": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          this.surface.setStreaming(null);
          const entries = transcriptEntriesFromMessages([message]);
          for (const entry of entries) this.surface.appendEntry({ ...entry, id: this.nextId(entry.kind) });
        }
        return;
      }
      case "tool_execution_start": {
        const { toolName, args } = event as { toolName?: string; args?: unknown };
        if (toolName) {
          const summary = briefArgs(args);
          this.append("tool", toolName, summary || "Running…");
        }
        return;
      }
      case "tool_execution_end": {
        const { toolName, result, isError } = event as { toolName?: string; result?: unknown; isError?: boolean };
        if (!toolName) return;
        if (isError) {
          this.appendError(`${toolName} failed`, result);
          return;
        }
        const card = toolResultCardLines(toolName, result);
        if (card) this.append("artifact", `${toolName} result`, card.join("\n"));
        else this.append("tool", `${toolName} completed`, messageText(result) || "Completed");
        return;
      }
      case "agent_start":
        this.surface.setHeaderState({ busy: true });
        return;
      case "agent_end":
        this.surface.setHeaderState({ busy: false });
        return;
      case "extension_ui_request":
        this.handleUiRequest(event as UiRequestEvent);
        return;
      case "ui_document": {
        const { document } = event as { document?: unknown };
        const card = toolResultCardLines("ui_document", document);
        if (card) this.append("artifact", "Interactive result", card.join("\n"));
        return;
      }
      default:
        return;
    }
  }

  private handleUiRequest(request: UiRequestEvent): void {
    switch (request.method) {
      case "notify":
        if (request.message) this.append(request.notifyType === "error" ? "error" : "notice", "Keating", sanitizeDiagnostic(request.message));
        return;
      case "setStatus":
        this.surface.setStatus(request.statusText || "Ready");
        return;
      case "set_editor_text":
        if (typeof request.text === "string") this.surface.setEditorText(request.text);
        return;
      case "setWidget":
        if (request.widgetKey) this.surface.setWidget(request.widgetKey, request.widgetLines, request.widgetPlacement);
        return;
      case "setTitle":
        if (request.title) this.surface.setTitle(request.title);
        return;
      case "select":
      case "confirm":
      case "input":
      case "editor":
        if (request.id) this.enqueueDialog(request as UiRequestEvent & { id: string });
        return;
      default:
        this.append("error", "Unsupported Pi UI request", `${request.method || "unknown"}. The request was cancelled explicitly.`);
        if (request.id) {
          void this.sendUiResponse(request.id, { cancelled: true, reason: "unsupported_ui_request" }).catch((error) => {
            this.appendError("Could not answer UI request", error);
          });
        }
        return;
    }
  }

  private enqueueDialog(request: UiRequestEvent & { id: string }): void {
    this.uiQueue = this.uiQueue
      .then(() => this.presentDialog(request))
      .catch((error) => {
        this.appendError("UI request failed", error);
      });
  }

  private async presentDialog(request: UiRequestEvent & { id: string }): Promise<void> {
    const title = request.title ?? "";
    try {
      switch (request.method) {
        case "select": {
          const value = await this.surface.presentSelect(title, request.options ?? []);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "confirm": {
          const confirmed = await this.surface.presentConfirm(title, request.message ?? "");
          await this.sendUiResponse(request.id, confirmed === undefined ? { cancelled: true } : { confirmed });
          return;
        }
        case "input": {
          const value = await this.surface.presentInput(title, request.placeholder);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "editor": {
          const value = await this.surface.presentEditor(title, request.prefill);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        default:
          await this.sendUiResponse(request.id, { cancelled: true });
      }
    } catch (error) {
      await this.sendUiResponse(request.id, { cancelled: true }).catch(() => {});
      throw error;
    }
  }
}
import { toolResultCardLines } from "../core/cards.js";

export type TranscriptEntryKind = "user" | "assistant" | "tool" | "artifact" | "notice" | "error";

export interface TranscriptEntry {
  id: string;
  kind: TranscriptEntryKind;
  title: string;
  body: string;
  detail?: string;
}

export interface TuiHeaderState {
  model: string;
  thinking: string;
  session: string;
  busy: boolean;
}

export const EMPTY_HEADER_STATE: TuiHeaderState = {
  model: "model unavailable",
  thinking: "off",
  session: "new session",
  busy: false,
};

export interface TuiCommand {
  id: "model" | "thinking" | "new-session" | "abort" | "shell";
  label: string;
  shortcut?: string;
  description: string;
}

export const TUI_COMMANDS: readonly TuiCommand[] = [
  { id: "model", label: "Change model", shortcut: "Ctrl+M", description: "Cycle to the next configured model" },
  { id: "thinking", label: "Change thinking", shortcut: "Ctrl+T", description: "Cycle the reasoning level" },
  { id: "new-session", label: "New session", shortcut: "Ctrl+N", description: "Start a fresh learning session" },
  { id: "abort", label: "Stop response", shortcut: "Ctrl+X", description: "Abort the active response" },
  { id: "shell", label: "Classic Pi shell", description: "Switch to the classic Pi interface" },
] as const;

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
}

export function messageText(message: unknown): string {
  const content = asRecord(message).content;
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((part) => {
      const candidate = asRecord(part);
      return candidate.type === "text" && typeof candidate.text === "string" ? candidate.text : "";
    })
    .filter(Boolean)
    .join("\n");
}

function stableId(prefix: string, message: Record<string, unknown>, index: number): string {
  const timestamp = typeof message.timestamp === "number" ? message.timestamp : index;
  const toolCall = typeof message.toolCallId === "string" ? `-${message.toolCallId}` : "";
  return `${prefix}-${timestamp}-${index}${toolCall}`;
}

export function sanitizeDiagnostic(value: unknown, maxLength = 700): string {
  let text: string;
  if (typeof value === "string") text = value;
  else if (value instanceof Error) text = value.message;
  else {
    try { text = JSON.stringify(value); }
    catch { text = String(value); }
  }

  const clean = text
    .replace(/\u001b\[[0-?]*[ -/]*[@-~]/g, "")
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, "")
    .replace(/\bBearer\s+[A-Za-z0-9._~+/=-]+/gi, "Bearer [redacted]")
    .replace(/\b(sk|pk|rk)-[A-Za-z0-9_-]{8,}\b/gi, "$1-[redacted]")
    .replace(/(["']?[A-Z][A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD)["']?\s*:\s*)["']?([^"',\s}]+)/g, "$1\"[redacted]\"")
    .replace(/\b([A-Z][A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD))\s*[=:]\s*([^\s,;]+)/g, "$1=[redacted]")
    .trim();
  return clean.length > maxLength ? `${clean.slice(0, maxLength - 1)}…` : clean;
}

export function transcriptEntriesFromMessages(messages: readonly unknown[]): TranscriptEntry[] {
  return messages.flatMap((raw, index): TranscriptEntry[] => {
    const message = asRecord(raw);
    const role = message.role;
    const body = messageText(message).trim();
    if (role === "user" && body) {
      return [{ id: stableId("user", message, index), kind: "user", title: "You", body }];
    }
    if (role === "assistant") {
      const entries: TranscriptEntry[] = [];
      if (body) entries.push({ id: stableId("assistant", message, index), kind: "assistant", title: "Keating", body });
      if ((message.stopReason === "error" || message.stopReason === "aborted") && typeof message.errorMessage === "string") {
        entries.push({
          id: stableId("assistant-error", message, index),
          kind: "error",
          title: message.stopReason === "aborted" ? "Response stopped" : "Response failed",
          body: sanitizeDiagnostic(message.errorMessage),
        });
      }
      return entries;
    }
    if (role === "toolResult") {
      const toolName = typeof message.toolName === "string" ? message.toolName : "tool";
      if (message.isError) {
        return [{
          id: stableId("tool-error", message, index),
          kind: "error",
          title: `${toolName} failed`,
          body: sanitizeDiagnostic(body || message.details || "The tool did not return a diagnostic."),
        }];
      }
      const card = toolResultCardLines(toolName, { content: message.content, details: message.details });
      return [{
        id: stableId("tool-result", message, index),
        kind: card ? "artifact" : "tool",
        title: card ? `${toolName} result` : toolName,
        body: card?.join("\n") || body || "Completed",
      }];
    }
    return [];
  });
}

const ENTRY_MARK: Record<TranscriptEntryKind, string> = {
  user: ">",
  assistant: "◆",
  tool: "→",
  artifact: "▣",
  notice: "·",
  error: "!",
};

export function transcriptEntryText(entry: TranscriptEntry): string {
  return `${ENTRY_MARK[entry.kind]} ${entry.title}\n${entry.body}${entry.detail ? `\n  ${entry.detail}` : ""}`;
}

export function transcriptText(entries: readonly TranscriptEntry[], streaming?: TranscriptEntry | null): string {
  const all = streaming ? [...entries, streaming] : entries;
  if (all.length === 0) {
    return "Ask a question, continue a learning goal, or press Ctrl+P to explore commands.";
  }
  return all.map(transcriptEntryText).join("\n\n");
}

export function headerText(state: TuiHeaderState): string {
  return [
    "KEATING",
    state.busy ? "THINKING" : "READY",
    state.model,
    `thinking ${state.thinking}`,
    state.session,
  ].join("  ·  ");
}

export function activityText(entries: readonly TranscriptEntry[], state: TuiHeaderState): string {
  const recent = entries.filter((entry) => entry.kind !== "user" && entry.kind !== "assistant").slice(-7);
  const lines = [
    "SESSION",
    state.session,
    "",
    "ACTIVITY",
    ...(recent.length
      ? recent.flatMap((entry) => [`${ENTRY_MARK[entry.kind]} ${entry.title}`, `  ${entry.body.split("\n")[0]?.slice(0, 24) ?? ""}`])
      : ["· No tool activity yet"]),
  ];
  return lines.join("\n");
}

export function showActivityRail(terminalWidth: number): boolean {
  return terminalWidth >= 100;
}

export function commandOption(command: TuiCommand): string {
  return `${command.label}${command.shortcut ? `  ·  ${command.shortcut}` : ""}  —  ${command.description}`;
}
import { KEATING_UI_PROTOCOL, KEATING_UI_VERSION, type JsonValue, type UiDocument, type UiDocumentKind } from "./types.js";

const KINDS = new Set<UiDocumentKind>(["quiz", "question", "goal", "deck", "image", "scene", "artifact", "generic"]);

function record(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function json(value: unknown): JsonValue {
  try { return JSON.parse(JSON.stringify(value)) as JsonValue; }
  catch { return String(value); }
}

export function isUiDocument(value: unknown): value is UiDocument {
  const item = record(value);
  return item.protocol === KEATING_UI_PROTOCOL
    && item.version === KEATING_UI_VERSION
    && typeof item.id === "string"
    && Number.isSafeInteger(item.revision)
    && KINDS.has(item.kind as UiDocumentKind)
    && !!item.payload && typeof item.payload === "object" && !Array.isArray(item.payload);
}

function inferredKind(toolName: string, details: Record<string, unknown>): UiDocumentKind {
  if (toolName === "quiz" || toolName === "grade_quiz" || details.quiz) return "quiz";
  if (toolName === "ask_user_question" || details.question || details.questions) return "question";
  if (details.goal || details.goals) return "goal";
  if (toolName === "deck" || details.deck || details.cards) return "deck";
  if (toolName === "generate_image" || details.image || details.imageUrl || details.dataUrl) return "image";
  if (toolName === "scene" || toolName === "animate" || details.scene || details.storyboard) return "scene";
  if (details.uri || details.filePath || /^(plan|map|verify)$/.test(toolName)) return "artifact";
  return "generic";
}

/** Convert tool/RPC payloads into the same wire shape used by the browser UI protocol. */
export function toolResultToUiDocument(toolName: string, result: unknown): UiDocument {
  const outer = record(result);
  if (isUiDocument(outer.uiDocument)) return outer.uiDocument;
  if (isUiDocument(result)) return result;
  const details = record(outer.details ?? result);
  const kind = inferredKind(toolName, details);
  let payload: Record<string, JsonValue>;
  if (kind === "quiz") payload = json(record(details.quiz ?? details)) as Record<string, JsonValue>;
  else if (kind === "question") payload = json(record(details.question ?? details)) as Record<string, JsonValue>;
  else if (kind === "goal") payload = json(record(details.goal ?? details)) as Record<string, JsonValue>;
  else if (kind === "deck") payload = json(record(details.deck ?? details)) as Record<string, JsonValue>;
  else if (kind === "image") payload = json(record(details.image ?? details)) as Record<string, JsonValue>;
  else if (kind === "scene") payload = json(record(details.scene ?? details)) as Record<string, JsonValue>;
  else if (kind === "artifact") payload = json(details) as Record<string, JsonValue>;
  else payload = { format: "json", data: json(details), originalKind: toolName };
  return { protocol: KEATING_UI_PROTOCOL, version: KEATING_UI_VERSION, id: String(details.id ?? `${toolName}-result`), revision: 0, kind, payload };
}
import type { JsonValue, UiDocument } from "./types.js";

function text(value: JsonValue | undefined): string { return typeof value === "string" ? value : ""; }
function list(value: JsonValue | undefined): Array<Record<string, JsonValue>> {
  return Array.isArray(value) ? value.filter((item): item is Record<string, JsonValue> => !!item && typeof item === "object" && !Array.isArray(item)) : [];
}

export interface UiDocumentPresentation { heading: string; body: string[] }

export function uiDocumentPresentation(document: UiDocument): UiDocumentPresentation {
  const p = document.payload;
  switch (document.kind) {
    case "quiz":
      return { heading: document.title ?? `Quiz: ${text(p.topic) || "Quiz"}`, body: list(p.questions).map((q, i) => `${i + 1}. ${text(q.prompt) || text(q.question) || "Question"}`) };
    case "question":
      return { heading: document.title ?? "Question", body: list(p.fields).map((q, i) => `${i + 1}. ${text(q.prompt) || text(q.question) || "Question"}`) };
    case "goal": {
      const steps = list(p.steps).map((step) => `${text(step.status) === "done" ? "[x]" : "[ ]"} ${text(step.title)}`);
      return { heading: document.title ?? `Goal: ${text(p.title) || "Learning goal"}`, body: [text(p.description), ...steps].filter(Boolean) };
    }
    case "deck":
      return { heading: document.title ?? (text(p.title) || "Flashcards"), body: list(p.cards).flatMap((card, i) => [`${i + 1}. ${text(card.front)}`, `   ${text(card.back)}`]) };
    case "image":
      return { heading: document.title ?? (text(p.title) || "Image"), body: [text(p.alt), text(p.url) || text(p.dataUrl) || "(image data unavailable in terminal)"].filter(Boolean) };
    case "scene":
      return { heading: document.title ?? `Scene${text(p.topic) ? `: ${text(p.topic)}` : ""}`, body: [text(p.summary), text(p.storyboard), text(p.body), text(p.markdown)].filter(Boolean) };
    case "artifact":
      return { heading: document.title ?? (text(p.label) || "Artifact"), body: [text(p.summary), text(p.uri) || text(p.filePath), text(p.content)].filter(Boolean) };
    default: {
      const content = text(p.content) || JSON.stringify(p.data ?? p, null, 2);
      return { heading: document.title ?? "Tool result", body: content.split("\n") };
    }
  }
}

